import { readFileSync } from "node:fs";
import { join } from "node:path";

export default async function (pi: any) {
  let models: any[] | undefined;
  try {
    models = JSON.parse(readFileSync(join(process.env.PI_CODING_AGENT_DIR ?? "", "provider-cache.json"), "utf8")).models;
  } catch {}
  if (!models) {
    try {
      const answer = await fetch("http://127.0.0.1:9/models", { signal: AbortSignal.timeout(3000) });
      models = (await answer.json()).models;
    } catch {
      return;
    }
  }
  pi.registerProvider("pkgprov", {
    baseUrl: "http://127.0.0.1:9/v1", apiKey: "none", api: "openai-completions", models,
  });
}

